# apps/core/mixins.py
from django.core.paginator import Paginator
from django.db.models import Q

class FilterableListMixin:
    """Mixin for list views with common filtering/pagination patterns"""
    paginate_by = 20
    search_fields = []  # Override in subclass
    filter_fields = []  # Override in subclass

    def get_search_query(self, request):
        return request.GET.get('search', '')

    def apply_search(self, queryset, search):
        if search and self.search_fields:
            q_objects = Q()
            for field in self.search_fields:
                q_objects |= Q(**{f'{field}__icontains': search})
            return queryset.filter(q_objects)
        return queryset

    def apply_filters(self, queryset, request):
        for field in self.filter_fields:
            value = request.GET.get(field)
            if value:
                queryset = queryset.filter(**{field: value})
        return queryset

    def paginate(self, queryset, request):
        paginator = Paginator(queryset, self.paginate_by)
        page = request.GET.get('page')
        return paginator.get_page(page)

# Usage in apps/inventory/views.py
class StockListView(FilterableListMixin):
    search_fields = ['material__code', 'material__name', 'warehouse__code']
    filter_fields = ['warehouse_id', 'material__material_type']

